/**
 * One existing provider's editor card, fully plugin-owned (v1.0.0 rewrite).
 * Primary field: a single write-only API key input; the collapsed
 * 「供应商」 section carries baseURL (plus displayName/protocol for a
 * hand-declared route), the 「模型」 section the model catalog with the
 * extension panel. Save semantics mirror the host card: minimal path ops
 * against the stored section with a revision fence, then the credential
 * write — the draft comes from the user layer, so a wholesale replace can
 * never delete fields outside the card.
 */

import { useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import type { CredentialInfo, LlmNativeAuth, SettingsNamespaceView } from '@deepseek-ai/dsh-api-remotes/client'
import { Tooltip } from '@deepseek-ai/dsh-client-ui-primitives'
import { deriveKeyRef, protocolChoices } from '../vendor/store.ts'
import type { ModelsOperations } from '../vendor/operations.ts'
import type { SettingsSchemaOperations } from '../vendor/schema-operations.ts'
import type { ModelDraft } from './compat.ts'
import { compatFailureMessage, modelDrafts, normalizeModelRow, pathOps, validateModelRows } from './compat.ts'
import { getPrefillIndex, sharedCatalogApi } from './models-index.ts'
import type { PrefillIndex } from './models-index.ts'
import type { ExtensionKey } from '../extension-meta.ts'
import { ApiKeyInput } from './ApiKeyInput.tsx'
import { ModelCatalog } from './ModelCatalog.tsx'
import styles from './models-plus.module.css'

/**
 * The official DeepSeek endpoint root, and the only one left to prefill: the
 * route is Messages-only. The host dropped the `protocol` field in
 * 0.1.7-alpha.1 and its resolver now refuses a configuration that still carries
 * one, so a chat-completions variant is neither offered nor reachable — reading
 * that old field only ever produced the bare root, which the adapter refuses
 * (host @ 0.1.7-rc.2, `PUBLIC_BASE_URL`).
 */
const DEEPSEEK_BASE_URL = 'https://api.deepseek.com/anthropic'

/** Per-adapter-family curated field sets (unknown namespaces get the hint alone). */
export type EditorLayout = 'deepseek' | 'pi-ai' | 'unknown'

/**
 * The official signed-in account route. It carries no API key and no base URL
 * of its own — the host renders the model catalog alone for it, under the
 * DeepSeek family's curated field set (host @ 0.1.7-rc.2).
 */
export const ACCOUNT_PROVIDER = 'deepseek-account'

/** The editor layout the owning namespace selects. */
export function layoutOf(ns: string): EditorLayout {
  if (ns === 'llm-deepseek') return 'deepseek'
  if (ns === 'llm-pi-ai') return 'pi-ai'
  return 'unknown'
}

/** A user-section subtree as a plain draft object (absent → empty). */
export function draftAt(
  schema: SettingsSchemaOperations,
  namespace: SettingsNamespaceView,
  path: readonly string[],
): Record<string, unknown> {
  const subtree = schema.getPath(namespace.user, path)
  if (typeof subtree !== 'object' || subtree === null || Array.isArray(subtree)) return {}
  return structuredClone(subtree) as Record<string, unknown>
}

/** The credential reference this profile resolves keys through. */
function refFor(
  schema: SettingsSchemaOperations,
  namespace: SettingsNamespaceView,
  path: readonly string[],
  provider: string,
): string {
  const profile = schema.getPath(namespace.value, path)
  const named = typeof profile === 'object' && profile !== null
    ? (profile as { apiKeyEnv?: unknown }).apiKeyEnv
    : undefined
  return typeof named === 'string' && named.length > 0 ? named : deriveKeyRef(provider)
}

/** Copy keys and state facts of the credential field, derived without the translation table. */
export interface CredentialView {
  /** References the adapter consults, display filter applied. */
  readonly visibleRefs: readonly string[]
  /** First visible reference: what the placeholder and the `?` bubble name. */
  readonly keyHint: string | undefined
  /** Placeholder copy key. */
  readonly placeholderKey: 'keyEnvLocked' | 'keyPlaceholder' | 'keyPlaceholderSaved' | 'keyPlaceholderFallback'
  /** Reference the placeholder's `{hint}` takes, when its copy carries one. */
  readonly placeholderHint: string | undefined
  /** Status-line copy key, absent when no line renders. */
  readonly hintKey?: 'keyFallbackMissing' | 'keyFallbackUnchecked' | 'keyFallbackDetected' | 'keyFallbackDetectedHidden'
  /** Reference the status line's `{hint}` takes. */
  readonly hintRef?: string
  /** Status-line tone class. */
  readonly hintTone?: 'notice' | 'savedNotice' | 'advancedHint'
  /** References the `?` bubble lists, absent when no bubble renders. */
  readonly helpRefs?: readonly string[]
  /** The route authenticates without a key: the field does not render. */
  readonly keyless: boolean
  /** The credential provider is read-only: the field renders disabled. */
  readonly locked: boolean
}

/**
 * Judge the credential field the way the official card does: a profile's named
 * reference decides alone, the directory's native variables stand in only when
 * the profile names none, endpoint variables are not credentials, and oauth
 * references stay out of the display without changing what the adapter reads.
 *
 * Kept free of the translation table so the judgement can be asserted directly.
 * @param input - resolved profile facts plus the batch described credential state.
 * @returns the copy keys and state facts the field renders from.
 */
export function credentialView(input: {
  readonly namedRef: string | undefined
  readonly nativeAuth: LlmNativeAuth | undefined
  readonly baseURLEnv: readonly string[]
  readonly keyDraft: string
  readonly credential: CredentialInfo | undefined
  readonly credentialChecks: Readonly<Record<string, CredentialInfo>> | undefined
}): CredentialView {
  const native = input.namedRef === undefined ? input.nativeAuth : undefined
  const authRefs = input.namedRef === undefined
    ? (native?.env ?? []).filter(ref => !input.baseURLEnv.includes(ref))
    : [input.namedRef]
  const visibleRefs = authRefs.filter(ref => !ref.toLowerCase().includes('oauth'))
  const keyHint = visibleRefs[0]
  const checked = authRefs.map(ref => [
    ref,
    input.credentialChecks?.[ref] ?? (ref === input.namedRef ? input.credential : undefined),
  ] as const)
  const detected = checked.find(([, info]) => info?.configured === true)
  const detectedRef = detected?.[0]
  const detectedVisible = detectedRef !== undefined && visibleRefs.includes(detectedRef) ? detectedRef : undefined
  const missingRefs = checked.length > 0 && checked.every(([, info]) => info?.configured === false)
  const savedCredential = detected?.[1]?.source === 'file'
  // A read-only provider answers from the launch environment: nothing this page
  // writes could replace it, so the field names that source and shows no state.
  const locked = input.credential?.writable === false
  const hint = locked || input.keyDraft.length > 0 || savedCredential || keyHint === undefined
    ? undefined
    : detectedRef === undefined
      ? missingRefs
        ? { key: 'keyFallbackMissing' as const, tone: 'notice' as const }
        : { key: 'keyFallbackUnchecked' as const, tone: 'advancedHint' as const }
      : detectedVisible === undefined
        ? { key: 'keyFallbackDetectedHidden' as const, tone: 'advancedHint' as const }
        : { key: 'keyFallbackDetected' as const, tone: 'savedNotice' as const }
  return {
    visibleRefs,
    keyHint,
    placeholderKey: locked
      ? 'keyEnvLocked'
      : keyHint === undefined
        ? 'keyPlaceholder'
        : savedCredential ? 'keyPlaceholderSaved' : 'keyPlaceholderFallback',
    placeholderHint: keyHint,
    ...hint === undefined ? {} : { hintKey: hint.key, hintRef: detectedVisible ?? keyHint, hintTone: hint.tone },
    ...visibleRefs.length === 0 ? {} : { helpRefs: visibleRefs },
    keyless: native !== undefined && native.env.length === 0 && native.oauth,
    locked,
  }
}

/** Props of {@link ProviderEditor}. */
export interface ProviderEditorProps {
  /** Provider route id. */
  provider: string
  /** Display name for the card title. */
  displayName: string
  /** Whether the adapter reports this route as hand-declared. */
  declared?: boolean
  /** The owning namespace view (schema, layers, secrets). */
  namespace: SettingsNamespaceView
  /** Settings-owned synchronous schema and immutable path operations. */
  schema: SettingsSchemaOperations
  /** Path from the section root to this provider's profile. */
  settingsPath: readonly string[]
  /** The Host operations this card writes and interrogates through. */
  operations: ModelsOperations
  /** Endpoint the route uses when its profile sets no `baseURL`; absent when the adapter reports none. */
  defaultBaseURL?: string
  /** Environment variables used by the provider to construct its endpoint. */
  baseURLEnv?: readonly string[]
  /** Authentication the route performs when its profile names no credential reference; absent when the adapter reports none. */
  nativeAuth?: LlmNativeAuth
  /** Redacted state of the profile's named credential reference, from the page snapshot. */
  credential?: CredentialInfo
  /** Redacted checks for the named reference or the provider's native variables, from the page snapshot. */
  credentialChecks?: Readonly<Record<string, CredentialInfo>>
  /** Section copy. */
  t: (key: ExtensionKey) => string
  /** Disable writes (read-only settings provider). */
  readOnly: boolean
  /** Close the editor; `changed` reports whether an Apply committed. */
  onClose: (changed: boolean) => void
}

/**
 * Render one existing provider's editing card.
 * @param props - the addressed profile plus wire faces.
 * @returns the editor card.
 */
export function ProviderEditor(props: ProviderEditorProps): ReactNode {
  const { namespace, schema, settingsPath, operations } = props
  const [draft, setDraft] = useState<Record<string, unknown>>(() => draftAt(schema, namespace, settingsPath))
  const [tab, setTab] = useState<'provider' | 'models'>('provider')
  const [keyDraft, setKeyDraft] = useState('')
  const [busy, setBusy] = useState(false)
  const [failure, setFailure] = useState<string | undefined>(undefined)
  const [committedOriginal, setCommittedOriginal] = useState<unknown>(
    () => schema.getPath(namespace.user, settingsPath),
  )
  const [expectedRevision, setExpectedRevision] = useState(() => namespace.revision)
  const root = useMemo(() => schema.rehydrate(namespace.schema), [namespace.schema, schema])
  const node = useMemo(() => schema.nodeAtPath(root, settingsPath), [root, schema, settingsPath])
  const fallback = schema.getPath(namespace.value, settingsPath)
  const disabled = props.readOnly || busy
  const accountProvider = props.provider === ACCOUNT_PROVIDER
  // The account route is modelled on the DeepSeek family although its namespace
  // is the adapter's own, so the curated field set applies to it (host @ 0.1.7-rc.2).
  const layout = accountProvider ? 'deepseek' : layoutOf(namespace.ns)
  const keyRef = refFor(schema, namespace, settingsPath, props.provider)
  const protocols = useMemo(
    () => layout === 'pi-ai' ? protocolChoices(namespace, schema) : [],
    [layout, namespace, schema],
  )
  /**
   * The pi-ai catalog, loaded only on the family that needs it: it answers the
   * protocol of a route that states none (a catalog route), which is what the
   * model panel judges compat switches by.
   */
  const [prefillIndex, setPrefillIndex] = useState<PrefillIndex | undefined>(undefined)
  useEffect(() => {
    if (layout !== 'pi-ai') return
    let stale = false
    void getPrefillIndex().then((loaded) => {
      if (!stale) setPrefillIndex(loaded)
    })
    return () => { stale = true }
  }, [layout])

  const stringAt = (source: unknown, key: string): string | undefined => {
    const value = schema.getPath(source, [key])
    return typeof value === 'string' && value.trim().length > 0 ? value : undefined
  }
  const setField = (key: string, next: string | undefined): void => {
    const value = next === undefined || next.trim().length === 0 ? undefined : next
    setDraft((current) => value === undefined
      ? schema.deletePath(current, [key])
      : schema.setPath(current, [key], value))
  }

  /**
   * The protocol every row of this route resolves to, resolved the way the
   * adapter resolves it: a hand-declared route's own `api` first — it overrides
   * the catalog for every model on the route — then the protocol the installed
   * catalog's entries for this route agree on, then nothing.
   *
   * The model panel needs it because the adapter judges each row's compat
   * switches by THIS protocol, not by the catalog entry the row was prefilled
   * from; without it a row can carry switches the route will refuse.
   */
  const routeApi = layout === 'pi-ai'
    ? (props.declared === true ? stringAt(draft, 'api') ?? stringAt(fallback, 'api') : undefined)
      ?? sharedCatalogApi(prefillIndex, props.provider)
    : undefined

  const modelFailure = validateModelRows(schema.getPath(draft, ['models']), routeApi)
  const keyFailure = ((): 'keyBlank' | 'keyIllegalCharacters' | undefined => {
    if (keyDraft.length === 0) return undefined
    const value = keyDraft.trim()
    if (value.length === 0) return 'keyBlank'
    // Mirrors the host's apiKeyFailure heuristics (env line / quoted / charset).
    if (/^[A-Z][A-Z0-9_]*=[^=]/.test(value)) return 'keyIllegalCharacters'
    const first = value[0]
    if ((first === '"' || first === '\'' || first === '`') && value.length > 1 && value.endsWith(first)) {
      return 'keyIllegalCharacters'
    }
    return /^[\x21-\x7E]+$/.test(value) ? undefined : 'keyIllegalCharacters'
  })()
  const keyValue = keyDraft.trim()

  const probe = {
    settingsNs: namespace.ns,
    provider: props.provider,
    ...(() => {
      const baseURL = stringAt(draft, 'baseURL') ?? stringAt(fallback, 'baseURL')
      return baseURL === undefined ? {} : { baseURL }
    })(),
    ...(() => {
      const api = layout === 'pi-ai' && props.declared === true
        ? stringAt(draft, 'api') ?? stringAt(fallback, 'api')
        : undefined
      return api === undefined ? {} : { api }
    })(),
    ...keyValue.length === 0 ? {} : { apiKey: keyValue },
  }

  /** The write for this card, or a failure message. */
  const applyOnce = async (): Promise<string | undefined> => {
    const ns = namespace.ns
    let next = layout === 'pi-ai' && stringAt(draft, 'apiKeyEnv') === undefined
      && stringAt(fallback, 'apiKeyEnv') === undefined && keyValue.length > 0
      ? schema.setPath(draft, ['apiKeyEnv'], keyRef)
      : draft
    const rowFailure = validateModelRows(schema.getPath(next, ['models']), routeApi)
    if (rowFailure !== undefined) {
      return rowFailure.key === 'modelCompatNotOffered'
        ? compatFailureMessage(rowFailure)
        : `模型 ${String(rowFailure.index + 1)}：${{
          modelIdRequired: '模型 ID 不能为空。',
          modelIdDuplicate: '模型 ID 不能重复。',
          modelNameInvalid: '显示名称不能为空。',
          modelContextInvalid: '上下文窗口须为正数，如 131072、256K、1M。',
          modelMaxTokensInvalid: '最大输出 token 数须为正数，如 8192、64K、1M。',
        }[rowFailure.key]}`
    }
    if (node !== undefined && settingsPath.length === 0) {
      const sectionError = schema.validate(node, next)
      if (sectionError !== undefined) return sectionError
    }
    // Stable YAML key order: normalize every drafted row before diffing.
    if (schema.hasPath(next, ['models'])) {
      next = schema.setPath(
        next,
        ['models'],
        modelDrafts(schema.getPath(next, ['models'])).map(normalizeModelRow),
      )
    }
    // Official semantic: a pi-ai route whose only act is activating the route
    // (no fields the card can see, no key yet) still writes an empty profile
    // so the route exists in the directory at all.
    const materializesNativeProfile = layout === 'pi-ai'
      && fallback === undefined
      && committedOriginal === undefined
      && Object.keys(next).length === 0
    const ops = materializesNativeProfile
      ? [{ op: 'set', path: [...settingsPath], value: {} }]
      : pathOps(settingsPath, committedOriginal, next)
    if (ops.length > 0) {
      const written = await operations.writeSettings(ns, ops, expectedRevision)
      if (written.kind !== 'written') return written.kind === 'conflict'
        ? '这张卡片打开期间，这些设置已被其他地方改动。请关闭后重新打开，在当前值上编辑。'
        : written.message
      setCommittedOriginal(schema.getPath(written.view.user, settingsPath))
      setExpectedRevision(written.view.revision)
      setDraft(next)
    }
    if (keyValue.length > 0) {
      const stored = await operations.storeCredential(keyRef, keyValue)
      if (stored !== undefined) return stored
    }
    setKeyDraft('')
    return undefined
  }

  const apply = async (): Promise<void> => {
    setBusy(true)
    setFailure(undefined)
    try {
      const applyFailure = await applyOnce()
      if (applyFailure !== undefined) {
        setFailure(applyFailure)
        return
      }
      props.onClose(true)
    } finally {
      setBusy(false)
    }
  }

  if (node === undefined) {
    return <p className={styles['error']}>{props.provider}: 无法解析设置路径</p>
  }

  /**
   * The catalog beneath the user layer: the composition entry's pin, or the
   * schema default — reading the effective value would echo the stored
   * override back the moment reset drops it.
   */
  const inheritedModels = (): unknown => {
    const pinned = schema.getPath(namespace.base, [...settingsPath, 'models'])
    return pinned ?? schema.nodeAtPath(root, [...settingsPath, 'models'])?.meta.default
  }
  const customModels = schema.getPath(draft, ['models'])
  const modelsOverridden = schema.hasPath(draft, ['models'])
  const models = modelDrafts(modelsOverridden ? customModels : inheritedModels())
  const defaultContextWindow = schema.getPath(fallback, ['defaultContextWindow'])
  const defaultMaxTokens = schema.getPath(fallback, ['maxTokens'])

  const view = credentialView({
    namedRef: stringAt(fallback, 'apiKeyEnv'),
    nativeAuth: props.nativeAuth,
    baseURLEnv: props.baseURLEnv ?? [],
    keyDraft,
    credential: props.credential,
    credentialChecks: props.credentialChecks,
  })
  const keyLocked = view.locked
  const credentialHint = view.hintKey === undefined
    ? undefined
    : props.t(view.hintKey).replace('{hint}', () => view.hintRef ?? '')
  // The bubble is the only place the fallback order is spelled out, and that
  // copy carries `$cwd`/`$DSH_HOME` literals: a replacement callback keeps them
  // out of the pattern interpretation.
  const keyHelp = view.helpRefs === undefined
    ? undefined
    : props.t('keyHelp').replace('{env}', () => (view.helpRefs ?? []).join(' / '))
  const authHelp = keyHelp === undefined
    ? null
    : (
        <Tooltip label={keyHelp} side="right" delayMs={0} focusDelayMs={0} portal openOnClick>
          <button type="button" className={styles['helpButton']} aria-label={props.t('authHelp')}>?</button>
        </Tooltip>
      )
  const keyPlaceholder = props.t(view.placeholderKey).replace('{hint}', () => view.placeholderHint ?? '')

  return (
    <div className={styles['editor']}>
      {layout === 'unknown'
        ? <p className={styles['advancedHint']}>其余字段存于 settings.yaml；请直接编辑对应段。（{namespace.ns}）</p>
        : accountProvider
          ? (
              /* No API key and no base URL: the platform's own model catalog is
                 the whole card, and its list is never fetched (host @ 0.1.7-rc.2). */
              <ModelCatalog
                models={models}
                overridden={modelsOverridden}
                routeApi={routeApi}
                defaultContextWindow={typeof defaultContextWindow === 'number' ? defaultContextWindow : undefined}
                defaultMaxTokens={typeof defaultMaxTokens === 'number' ? defaultMaxTokens : undefined}
                probe={probe}
                probeBlocked={keyFailure}
                hideFetch
                operations={operations}
                disabled={disabled}
                onChange={(rows: ModelDraft[]) => {
                  setDraft(current => schema.setPath(current, ['models'], rows))
                }}
                onReset={() => { setDraft(current => schema.deletePath(current, ['models'])) }}
              />
            )
          : (
            <>
              <div className={styles['tabs']}>
                <div className={styles['tabBar']} role="tablist">
                  <button type="button" role="tab" aria-selected={tab === 'provider'} className={tab === 'provider' ? `${styles['tabButton']} ${styles['tabButtonActive']}` : styles['tabButton']} onClick={() => { setTab('provider') }}>供应商</button>
                  <button type="button" role="tab" aria-selected={tab === 'models'} className={tab === 'models' ? `${styles['tabButton']} ${styles['tabButtonActive']}` : styles['tabButton']} onClick={() => { setTab('models') }}>模型</button>
                </div>                <div className={styles['tabPanel']} role="tabpanel" hidden={tab !== 'provider'}>
                  {/* Offered for every pi-ai route, not only hand-declared ones.
                      The display name is a provider-level field the adapter
                      defaults to the route key and honours as an override, and
                      for a catalog route it is the only way to relabel: the key
                      itself cannot change without breaking the catalog match
                      and every credential ref derived from it. */}
                  {layout === 'pi-ai'
                    ? (
                        <div className={styles['field']}>
                          <label className={styles['fieldLabel']}>显示名称</label>
                          <input
                            className={styles['input']}
                            type="text"
                            value={stringAt(draft, 'displayName') ?? ''}
                            placeholder={stringAt(schema.getPath(namespace.base, settingsPath), 'displayName')
                              ?? props.provider}
                            aria-label="显示名称"
                            disabled={disabled}
                            onChange={(event) => { setField('displayName', event.target.value) }}
                          />
                        </div>
                      )
                    : null}
                  {view.keyless
                    ? null
                    : (
                        <div className={styles['field']}>
                          <span className={styles['fieldLabel']}>
                            {props.t('keyInput')}
                            {authHelp}
                          </span>
                          <ApiKeyInput
                            t={props.t}
                            value={keyDraft}
                            placeholder={keyPlaceholder}
                            aria-label={props.t('keyInput')}
                            aria-invalid={keyFailure !== undefined}
                            aria-describedby={credentialHint === undefined ? undefined : `${props.provider}-credential-hint`}
                            disabled={disabled || keyLocked}
                            onChange={(event) => { setKeyDraft(event.target.value) }}
                          />
                          {credentialHint === undefined
                            ? null
                            : (
                                <p id={`${props.provider}-credential-hint`} className={styles[view.hintTone ?? 'advancedHint']}>
                                  {credentialHint}
                                </p>
                              )}
                          {keyFailure === undefined
                            ? null
                            : <p className={styles['error']}>{props.t(keyFailure)}</p>}
                        </div>
                      )}
                  <div className={styles['field']}>
                    <label className={styles['fieldLabel']}>API 地址</label>
                    <input
                      className={styles['input']}
                      type="text"
                      value={stringAt(draft, 'baseURL') ?? ''}
                      placeholder={layout === 'deepseek'
                        ? DEEPSEEK_BASE_URL
                        : stringAt(fallback, 'baseURL') ?? '提供方默认'}
                      aria-label="API 地址"
                      disabled={disabled}
                      onChange={(event) => { setField('baseURL', event.target.value === '' ? undefined : event.target.value) }}
                    />
                    {layout === 'deepseek'
                      ? <span className={styles['advancedHint']}>该路由固定使用 Messages 协议，地址须指向兼容该协议的端点。</span>
                      : null}
                  </div>
                  {layout === 'pi-ai' && props.declared === true
                    ? (
                        <div className={styles['field']}>
                          <label className={styles['fieldLabel']}>API 协议</label>
                          <select
                            className={`${styles['input']} ${styles['selectInput']}`}
                            value={stringAt(draft, 'api') ?? stringAt(fallback, 'api') ?? ''}
                            aria-label="API 协议"
                            disabled={disabled}
                            onChange={(event) => { setField('api', event.target.value) }}
                          >
                            {(stringAt(draft, 'api') ?? stringAt(fallback, 'api')) === undefined
                              ? <option value="">未选择</option>
                              : null}
                            {protocols.map(choice => <option key={choice} value={choice}>{choice}</option>)}
                          </select>
                        </div>
                      )
                    : null}
                </div>
                <div className={styles['tabPanel']} role="tabpanel" hidden={tab !== 'models'}>
                  <ModelCatalog
                    models={models}
                    overridden={modelsOverridden}
                    routeApi={routeApi}
                    defaultContextWindow={typeof defaultContextWindow === 'number' ? defaultContextWindow : undefined}
                    defaultMaxTokens={typeof defaultMaxTokens === 'number' ? defaultMaxTokens : undefined}
                    probe={probe}
                    probeBlocked={keyFailure}
                    hideFetch={layout === 'deepseek'}
                    operations={operations}
                    disabled={disabled}
                    onChange={(rows: ModelDraft[]) => {
                      setDraft(current => schema.setPath(current, ['models'], rows))
                    }}
                    onReset={() => { setDraft(current => schema.deletePath(current, ['models'])) }}
                  />
                </div>
              </div>
            </>
          )}

      {failure !== undefined ? <p className={styles['error']}>{failure}</p> : null}
      {modelFailure === undefined
        ? null
        : (
            <p className={styles['advancedHint']}>
              {modelFailure.key === 'modelCompatNotOffered'
                ? compatFailureMessage(modelFailure)
                : `模型 ${String(modelFailure.index + 1)}：${modelFailure.key}`}
            </p>
          )}

      <div className={styles['editorActions']}>
        <button
          type="button"
          className={styles['secondaryButton']}
          disabled={busy}
          onClick={() => { props.onClose(false) }}
        >
          取消
        </button>
        <button
          type="button"
          className={styles['primaryButton']}
          disabled={disabled || layout === 'unknown' || modelFailure !== undefined
            || keyFailure !== undefined}
          onClick={() => { void apply() }}
        >
          {busy ? '保存中…' : '保存'}
        </button>
      </div>
    </div>
  )
}
